1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_RATE = 0.1;
3	const DEDUCTIBLE = 100;
4	const CAP_MULTIPLIER = 2;
5	
6	interface CatalogEntry {
7	  basePremium: number;
8	  insuranceValue: number;
9	}
10	
11	const CATALOG: Record<string, CatalogEntry> = {
12	  sword: { basePremium: 100, insuranceValue: 1000 },
13	  amulet: { basePremium: 60, insuranceValue: 600 },
14	  staff: { basePremium: 80, insuranceValue: 800 },
15	  potion: { basePremium: 40, insuranceValue: 400 },
16	  rune: { basePremium: 25, insuranceValue: 250 },
17	  moonstone: { basePremium: 25, insuranceValue: 250 },
18	};
19	
20	const basePremiumOf = (type: string): number => CATALOG[type]?.basePremium ?? 0;
21	const insuranceValueOf = (type: string): number => CATALOG[type]?.insuranceValue ?? 0;
22	
23	const sumBy = <T>(items: readonly T[], value: (item: T) => number): number =>
24	  items.reduce((total, item) => total + value(item), 0);
25	
26	interface ConditionalRate<T> {
27	  applies: (subject: T) => boolean;
28	  rate: number;
29	}
30	
31	const sumApplicableRates = <T>(rates: readonly ConditionalRate<T>[], subject: T): number =>
32	  sumBy(rates, ({ applies, rate }) => (applies(subject) ? rate : 0));
33	
34	interface Item {
35	  type: string;
36	  material?: string;
37	  enchantment?: number;
38	  cursed?: boolean;
39	}
40	
41	const HIGH_ENCHANTMENT_PREMIUM_THRESHOLD = 5;
42	
43	const enchantmentOf = (item: Item): number => item.enchantment ?? 0;
44	
45	const isCursed = (item: Item): boolean => item.cursed === true;
46	const hasHighEnchantmentForPremium = (item: Item): boolean =>
47	  enchantmentOf(item) >= HIGH_ENCHANTMENT_PREMIUM_THRESHOLD;
48	
49	const SURCHARGE_RATES: ReadonlyArray<ConditionalRate<Item>> = [
50	  { applies: isCursed, rate: 0.5 },
51	  { applies: hasHighEnchantmentForPremium, rate: 0.3 },
52	];
53	
54	const itemSurcharge = (item: Item): number =>
55	  basePremiumOf(item.type) * sumApplicableRates(SURCHARGE_RATES, item);
56	
57	const itemsSurcharge = (items: Item[]): number => sumBy(items, itemSurcharge);
58	
59	interface QuoteStep {
60	  op: "quote";
61	  items: Item[];
62	}
63	
64	interface Damage {
65	  itemType: string;
66	  amount: number;
67	}
68	
69	interface ClaimStep {
70	  op: "claim";
71	  policy: number;
72	  incident: {
73	    cause: string;
74	    damages: Damage[];
75	  };
76	}
77	
78	type Step = QuoteStep | ClaimStep;
79	
80	interface Customer {
81	  yearsWithMHPCO: number;
82	}
83	
84	interface Scenario {
85	  customer: Customer;
86	  steps: Step[];
87	}
88	
89	interface QuoteResult {
90	  premium: number;
91	}
92	
93	interface ClaimResult {
94	  payout: number;
95	  remainingCap: number;
96	}
97	
98	type StepResult = QuoteResult | ClaimResult;
99	
100	interface ScenarioResult {
101	  results: StepResult[];
102	}
103	
104	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
105	const COMPONENT_BLOCK_SIZE = 3;
106	const COMPONENT_BLOCK_BASE = 60;
107	
108	const roundUpInMHPCOsFavor = (amount: number): number => Math.ceil(amount);
109	const roundDownInMHPCOsFavor = (amount: number): number => Math.floor(amount);
110	
111	const countByKey = <T>(items: readonly T[], keyOf: (item: T) => string): Map<string, number> => {
112	  const counts = new Map<string, number>();
113	  for (const item of items) {
114	    const key = keyOf(item);
115	    counts.set(key, (counts.get(key) ?? 0) + 1);
116	  }
117	  return counts;
118	};
119	
120	const countItemsByType = (items: Item[]): Map<string, number> =>
121	  countByKey(items, (item) => item.type);
122	
123	const isComponentBlock = (type: string, count: number): boolean =>
124	  COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE;
125	
126	const basePremiumForSameTypeItems = (type: string, count: number): number =>
127	  isComponentBlock(type, count) ? COMPONENT_BLOCK_BASE : basePremiumOf(type) * count;
128	
129	const itemsBasePremium = (items: Item[]): number =>
130	  sumBy([...countItemsByType(items)], ([type, count]) => basePremiumForSameTypeItems(type, count));
131	
132	const firstInsuranceSurcharge = (base: number): number => base * FIRST_INSURANCE_RATE;
133	
134	const LOYALTY_YEARS_THRESHOLD = 2;
135	const LOYALTY_DISCOUNT_RATE = 0.2;
136	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
137	
138	interface QuoteContext {
139	  customer: Customer;
140	  isFollowUp: boolean;
141	}
142	
143	const isLoyalCustomer = ({ customer }: QuoteContext): boolean =>
144	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
145	
146	const isFollowUpQuote = ({ isFollowUp }: QuoteContext): boolean => isFollowUp;
147	
148	const DISCOUNT_RATES: ReadonlyArray<ConditionalRate<QuoteContext>> = [
149	  { applies: isLoyalCustomer, rate: LOYALTY_DISCOUNT_RATE },
150	  { applies: isFollowUpQuote, rate: FOLLOW_UP_DISCOUNT_RATE },
151	];
152	
153	const totalDiscount = (base: number, context: QuoteContext): number =>
154	  base * sumApplicableRates(DISCOUNT_RATES, context);
155	
156	const quotePremium = ({ items }: QuoteStep, context: QuoteContext): number => {
157	  const base = itemsBasePremium(items);
158	  const premiumBeforeFee =
159	    base + itemsSurcharge(items) + firstInsuranceSurcharge(base) - totalDiscount(base, context);
160	  return roundUpInMHPCOsFavor(premiumBeforeFee + PROCESSING_FEE);
161	};
162	
163	interface Policy {
164	  items: Item[];
165	  remainingCap: number;
166	}
167	
168	const createPolicy = (step: QuoteStep): Policy => ({
169	  items: step.items,
170	  remainingCap: sumBy(step.items, (item) => insuranceValueOf(item.type)) * CAP_MULTIPLIER,
171	});
172	
173	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
174	const FULL_REIMBURSEMENT_RATE = 1;
175	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
176	
177	const hasHighEnchantmentForClaim = (item: Item): boolean =>
178	  enchantmentOf(item) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD;
179	
180	const reimbursementRate = (item: Item): number =>
181	  hasHighEnchantmentForClaim(item) ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
182	
183	const damagePayout = (damage: Damage, item: Item): number =>
184	  Math.max(0, damage.amount * reimbursementRate(item) - DEDUCTIBLE);
185	
186	const findItemByType = (policy: Policy, itemType: string): Item => {
187	  const item = policy.items.find((candidate) => candidate.type === itemType);
188	  if (item === undefined) throw new Error(`Claim references item not in policy: ${itemType}`);
189	  return item;
190	};
191	
192	const payoutForDamage = (damage: Damage, policy: Policy): number =>
193	  damagePayout(damage, findItemByType(policy, damage.itemType));
194	
195	const calculatePayout = (damages: Damage[], policy: Policy): number => {
196	  const rawPayout = sumBy(damages, (damage) => payoutForDamage(damage, policy));
197	  return roundDownInMHPCOsFavor(Math.min(rawPayout, policy.remainingCap));
198	};
199	
200	const assertNonNegativeDamage = (damage: Damage): void => {
201	  if (damage.amount < 0) throw new Error(`Negative damage amount: ${damage.amount}`);
202	};
203	
204	const assertDamageCountsWithinPolicy = (damages: Damage[], policy: Policy): void => {
205	  const insuredCounts = countItemsByType(policy.items);
206	  const damageCounts = countByKey(damages, (damage) => damage.itemType);
207	  for (const [type, count] of damageCounts) {
208	    if (count > (insuredCounts.get(type) ?? 0)) {
209	      throw new Error(`More damages of type ${type} than items insured`);
210	    }
211	  }
212	};
213	
214	const processClaim = (step: ClaimStep, policies: Policy[]): ClaimResult => {
215	  step.incident.damages.forEach(assertNonNegativeDamage);
216	  const policy = policies[step.policy];
217	  assertDamageCountsWithinPolicy(step.incident.damages, policy);
218	  const payout = calculatePayout(step.incident.damages, policy);
219	  policy.remainingCap -= payout;
220	  return { payout, remainingCap: policy.remainingCap };
221	};
222	
223	const assertKnownItemType = (item: Item): void => {
224	  if (!(item.type in CATALOG)) throw new Error(`Unknown item type: ${item.type}`);
225	};
226	
227	const processQuote = (
228	  step: QuoteStep,
229	  customer: Customer,
230	  policies: Policy[],
231	): QuoteResult => {
232	  step.items.forEach(assertKnownItemType);
233	  const context: QuoteContext = { customer, isFollowUp: policies.length > 0 };
234	  policies.push(createPolicy(step));
235	  return { premium: quotePremium(step, context) };
236	};
237	
238	const processStep = (
239	  step: Step,
240	  customer: Customer,
241	  policies: Policy[],
242	): StepResult =>
243	  step.op === "quote"
244	    ? processQuote(step, customer, policies)
245	    : processClaim(step, policies);
246	
247	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
248	  const policies: Policy[] = [];
249	  const results = steps.map((step) => processStep(step, customer, policies));
250	  return { results };
251	};
